<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {analytics,selectedDate,shift,numberText as fmt} from '../lib/analyticsApi';
 import RunOverlay from './RunOverlay.svelte';
 interface Run {id:string;date:string;name:string;type:string;distanceMeters:number|null;durationSeconds:number|null;paceSecondsPerKm:number|null;avgHeartRate:number|null;elevationGain:number|null;averageCadence?:number;strideLength?:number;groundContactTime?:number;averagePower?:number;verticalOscillation?:number;verticalRatio?:number;reason?:string;trace?:Record<string,unknown>[];differences?:Record<string,number|null>}
 let open=$state(false),end=$state(''),query=$state(''),offset=$state(0),total=$state(0),runs=$state<Run[]>([]),suggested=$state<Run[]>([]),selected=$state<string[]>([]),same=$state(false),result=$state<{runs:Run[];routeStatus:string;warnings:string[]}|null>(null),error=$state(''),busy=$state(false);
 let controller:AbortController|undefined;
 const pace=(v:number|null)=>{if(v==null)return '—';const n=Math.round(v);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}/km`};
 async function search(){controller?.abort();const c=new AbortController();controller=c;busy=true;error='';try{const r=await analytics<{items:Run[];total:number;suggestions:Run[]}>(`/activities?${new URLSearchParams({start:shift(end,-364),end,q:query,offset:String(offset),reference:selected[0]??''})}`,c.signal);if(!c.signal.aborted){runs=r.items;total=r.total;suggested=r.suggestions}}catch(e){if(!c.signal.aborted)error=e instanceof Error?e.message:'Pretraga nije dostupna.'}finally{if(controller===c)busy=false}}
 async function compare(){controller?.abort();const c=new AbortController();controller=c;busy=true;error='';result=null;try{const r=await analytics<{runs:Run[];routeStatus:string;warnings:string[]}>('/running-comparison',c.signal,{activityIds:selected,sameRouteConfirmed:same});if(!c.signal.aborted)result=r}catch(e){if(!c.signal.aborted)error=e instanceof Error?e.message:'Usporedba nije dostupna.'}finally{if(controller===c)busy=false}}
 function choose(id:string,checked:boolean){selected=checked?[...selected,id]:selected.filter(v=>v!==id);result=null;same=false;void search()}
 onMount(()=>{end=selectedDate();const change=()=>{controller?.abort();end=selectedDate();selected=[];same=false;result=null;offset=0;runs=[];suggested=[];if(open)void search()};document.getElementById('date')?.addEventListener('change',change);return()=>document.getElementById('date')?.removeEventListener('change',change)});onDestroy(()=>controller?.abort());
 const metrics=[['distanceMeters','Udaljenost','m'],['durationSeconds','Trajanje','s'],['avgHeartRate','Puls','bpm'],['elevationGain','Uspon','m'],['averageCadence','Kadenca','spm'],['strideLength','Duljina koraka','cm'],['groundContactTime','Dodir tla','ms'],['averagePower','Snaga','W'],['verticalOscillation','Vertikalna oscilacija','cm'],['verticalRatio','Vertikalni omjer','%']];
</script>
<details class="panel analytics-panel" id="running-comparison" ontoggle={e=>{open=e.currentTarget.open;if(open)void search();else controller?.abort()}}><summary><strong>Usporedi ponovljena trčanja</strong></summary>
 <p class="quiet">Odaberi 2–5 aktivnosti iz zadnjih 365 dana. Prvo odabrano trčanje je referenca. Slična udaljenost ne potvrđuje istu rutu.</p>
 <form class="analytics-controls" onsubmit={e=>{e.preventDefault();offset=0;void search()}}><label>Naziv trčanja<input bind:value={query} maxlength="100"/></label><button class="btn">Pretraži</button></form>
 {#if suggested.length}<details><summary>Prijedlozi sličnih aktivnosti</summary>{#each suggested as run}<p>{run.date} · {run.name} · {run.reason} <button class="btn" disabled={selected.includes(run.id)||selected.length>=5} onclick={()=>choose(run.id,true)}>Dodaj u usporedbu</button></p>{/each}</details>{/if}
 {#each runs as run}<div class="analytics-row"><input type="checkbox" id={`compare-run-${run.id}`} checked={selected.includes(run.id)} disabled={!/^\d{1,20}$/.test(run.id)||(!selected.includes(run.id)&&selected.length>=5)} onchange={e=>choose(run.id,e.currentTarget.checked)}/><label for={`compare-run-${run.id}`}>{run.date} · {run.name}<br/><span class="quiet">{fmt(run.distanceMeters==null?null:run.distanceMeters/1000)} km · {pace(run.paceSecondsPerKm)} · {fmt(run.avgHeartRate,0)} bpm</span></label><a href="#activity-details" onclick={()=>document.dispatchEvent(new CustomEvent('analytics:activity-select',{detail:run}))}>Detalji</a></div>{:else}<p>{busy?'Učitavam aktivnosti…':'Nema dostupnih trčanja u odabranom rasponu ili pretrazi.'}</p>{/each}
 <div class="analytics-controls"><button class="btn" disabled={offset===0} onclick={()=>{offset=Math.max(0,offset-50);void search()}}>Prethodno</button><span>{offset+Math.min(1,total)}–{Math.min(offset+50,total)} od {total}</span><button class="btn" disabled={offset+50>=total} onclick={()=>{offset+=50;void search()}}>Sljedeće</button></div>
 <p>Odabrano {selected.length}/5 <button class="btn" onclick={()=>{selected=[];result=null;same=false}}>Očisti odabir</button></p><label><input type="checkbox" bind:checked={same} onchange={()=>result=null}/> Potvrđujem da su odabrana trčanja na istoj poznatoj ruti</label><p><button class="btn" disabled={selected.length<2||busy} onclick={()=>void compare()}>{busy?'Učitavam…':'Usporedi trčanja'}</button></p>
 {#if error}<p class="analytics-error" role="status">{error}</p>{/if}
 {#if result}<p><b>{result.routeStatus}</b></p>{#each result.warnings as note}<p class="quiet">{note}</p>{/each}<div class="analytics-table"><table><thead><tr><th>Pokazatelj</th>{#each result.runs as r}<th>{r.date}<br/>{r.name}</th>{/each}</tr></thead><tbody><tr><th>Tempo</th>{#each result.runs as r}<td>{pace(r.paceSecondsPerKm)}<br/>Razlika {fmt(r.differences?.paceSecondsPerKm)} s/km</td>{/each}</tr>{#each metrics as [key,label,unit]}<tr><th>{label}</th>{#each result.runs as r}<td>{fmt((r as unknown as Record<string,unknown>)[key])} {unit}{#if key==='elevationGain'||key==='avgHeartRate'}<br/>Razlika {fmt(r.differences?.[key])} {unit}{/if}</td>{/each}</tr>{/each}</tbody></table></div>
 <RunOverlay runs={result.runs}/>{/if}
</details>
